#!/usr/bin/env python3
"""Generate records.json for this packet.

Semantic records only: the function model, the layout, the dispatch
table, the caller census, the case ledger, the engine callees and the
open unknowns. Hashes come from functions.tsv (generated by
gen_records.py from the binary + the vendor census); case counts
come from cases.tsv.
"""

import json
from pathlib import Path

PACKET = Path(__file__).resolve().parent
ROOT = PACKET.parents[3]
DIGEST = "a6e2897cd051213d004802deca416e8eca62b7a8278fa39f249e98c3867b5301"


def _functions_tsv():
    rows = []
    with open(PACKET / "functions.tsv") as fh:
        header = fh.readline().rstrip("\n").split("\t")
        for line in fh:
            rows.append(dict(zip(header, line.rstrip("\n").split("\t"))))
    return rows


def _case_groups():
    groups = {}
    with open(PACKET / "cases.tsv") as fh:
        header = fh.readline().rstrip("\n").split("\t")
        for line in fh:
            row = dict(zip(header, line.rstrip("\n").split("\t")))
            groups[row["group"]] = groups.get(row["group"], 0) + 1
    return groups


